{
  "id": "vuln-phpldapadmin-dd6e9583",
  "pattern": "$REQUEST.setRequestHeader('Connection', 'close');",
  "pattern_not": [
    "$REQUEST.setRequestHeader('Content-length', $LENGTH);",
    "$REQUEST.setRequestHeader('Connection', 'close');"
  ],
  "languages": [
    "javascript"
  ],
  "message": "Setting the 'Connection' header to 'close' can lead to unexpected behavior in HTTP requests. It is recommended to remove this header to prevent potential issues with persistent connections.",
  "severity": "WARNING",
  "metadata": {
    "category": "security",
    "cwe": "CWE-444",
    "owasp": "A6:2017-Security Misconfiguration"
  }
}

